class DHPCTIndividual:
    """
    Represents a hierarchical Perceptual Control Theory system with Keras model.
    
    This class manages the creation, compilation, execution, and evolution of
    hierarchical control systems following PCT principles.
    """
    
    @staticmethod
    def _expand_activation_funcs(
        activation_funcs: "Union[str, List[str], Dict[str, Any]]",
        num_levels: int
    ) -> Dict[str, Any]:
        """Expand activation_funcs shorthand to full dict form.
        
        Accepts three input forms and always returns an expanded dict:
          - ``str``: applied uniformly to all function types and levels.
          - ``list[str]``: per-level activation applied to all function types.
          - ``dict``: already in full form; validated and returned as-is.
        
        The returned dict has keys ``"perception"``, ``"reference"``,
        ``"output"`` (each a ``list[str]`` of length *num_levels*) and
        ``"actions"`` (a scalar ``str``).
        
        Args:
            activation_funcs: Raw value from the caller.
            num_levels: ``len(levels)`` — the expected length of per-level lists.
        
        Returns:
            Fully-expanded activation dict.
        
        Raises:
            ValueError: On length mismatch or missing/invalid dict keys.
        """
        func_type_keys = ("perception", "reference", "output")

        # --- str shorthand: broadcast to every slot -------------------------
        if isinstance(activation_funcs, str):
            per_level = [activation_funcs] * num_levels
            return {
                "perception": list(per_level),
                "reference": list(per_level),
                "output": list(per_level),
                "actions": activation_funcs,
            }

        # --- list shorthand: per-level, applied to all function types -------
        if isinstance(activation_funcs, list):
            if len(activation_funcs) != num_levels:
                raise ValueError(
                    f"activation_funcs length ({len(activation_funcs)}) "
                    f"must match levels length ({num_levels})"
                )
            return {
                "perception": list(activation_funcs),
                "reference": list(activation_funcs),
                "output": list(activation_funcs),
                "actions": "linear",  # Actions layer defaults to linear
            }

        # --- dict form: validate and return as-is ---------------------------
        if isinstance(activation_funcs, dict):
            # Check required keys
            for key in func_type_keys:
                if key not in activation_funcs:
                    raise ValueError(f"activation_funcs dict must contain '{key}' key")
                if not isinstance(activation_funcs[key], list):
                    raise ValueError(f"activation_funcs['{key}'] must be a list")
                if len(activation_funcs[key]) != num_levels:
                    raise ValueError(
                        f"activation_funcs['{key}'] length ({len(activation_funcs[key])}) "
                        f"must match levels length ({num_levels})"
                    )
            
            if "actions" not in activation_funcs:
                raise ValueError("activation_funcs dict must contain 'actions' key")
            if not isinstance(activation_funcs["actions"], str):
                raise ValueError("activation_funcs['actions'] must be a string")
            
            # Return a copy to avoid external mutations
            return {
                "perception": list(activation_funcs["perception"]),
                "reference": list(activation_funcs["reference"]),
                "output": list(activation_funcs["output"]),
                "actions": activation_funcs["actions"],
            }

        # --- Invalid input ---------------------------------------------------
        raise ValueError(
            f"activation_funcs must be str, list, or dict; got {type(activation_funcs)}"
        )
    
    @staticmethod
    def _expand_smooth_factors(
        smooth_factors: "Union[None, float, List[float], Dict[str, Any]]",
        activation_funcs: Dict[str, Any],
        num_levels: int
    ) -> Dict[str, Any]:
        """Expand smooth_factors shorthand to full dict form matching activation_funcs structure.
        
        Args:
            smooth_factors: Raw smooth factors specification
            activation_funcs: Already-expanded activation functions dict
            num_levels: Number of levels in hierarchy
            
        Returns:
            Fully-expanded smooth factors dict matching activation_funcs structure
        """
        # None is handled in __init__, where level and action dimensions are
        # available for per-unit random initialization. This fallback is kept for
        # direct helper calls.
        if smooth_factors is None:
            return {
                "perception": [0.5] * num_levels,
                "reference": [0.5] * num_levels, 
                "output": [0.5] * num_levels,
                "actions": 0.5
            }
        
        # Single float: broadcast to all
        if isinstance(smooth_factors, (int, float)):
            factor = float(smooth_factors)
            return {
                "perception": [factor] * num_levels,
                "reference": [factor] * num_levels,
                "output": [factor] * num_levels,
                "actions": factor
            }
        
        # List: per-level applied to all function types
        if isinstance(smooth_factors, list):
            if len(smooth_factors) != num_levels:
                raise ValueError(
                    f"smooth_factors length ({len(smooth_factors)}) "
                    f"must match levels length ({num_levels})"
                )
            return {
                "perception": list(smooth_factors),
                "reference": list(smooth_factors),
                "output": list(smooth_factors),
                "actions": smooth_factors[-1]  # Use last level for actions
            }
        
        # Dict: validate structure matches activation_funcs
        if isinstance(smooth_factors, dict):
            result = {}
            
            for key in ["perception", "reference", "output"]:
                if key in smooth_factors:
                    if not isinstance(smooth_factors[key], list):
                        raise ValueError(f"smooth_factors['{key}'] must be a list")
                    if len(smooth_factors[key]) != num_levels:
                        raise ValueError(
                            f"smooth_factors['{key}'] length ({len(smooth_factors[key])}) "
                            f"must match levels length ({num_levels})"
                        )
                    result[key] = [
                        item if isinstance(item, (list, tuple)) else float(item)
                        for item in smooth_factors[key]
                    ]
                else:
                    # Default to 0.5 for missing keys  
                    result[key] = [0.5] * num_levels
            
            if "actions" in smooth_factors:
                actions_value = smooth_factors["actions"]
                if isinstance(actions_value, (list, tuple)):
                    result["actions"] = list(actions_value)
                elif isinstance(actions_value, (int, float)):
                    result["actions"] = float(actions_value)
                else:
                    raise ValueError("smooth_factors['actions'] must be a number or list")
            else:
                result["actions"] = 0.5
                
            return result
        
        raise ValueError(
            f"smooth_factors must be None, number, list, or dict; got {type(smooth_factors)}"
        )

    @staticmethod
    def _random_smooth_factors(
        levels: List[int],
        activation_funcs: Dict[str, Any],
        action_units: int,
        rng: np.random.Generator,
    ) -> Dict[str, Any]:
        """Create random initial smooth factors for every active smooth layer.

        Each unit in an ``ExponentialSmoothLayer`` receives its own alpha in
        ``[0, 1)``.  Non-smooth slots keep the legacy placeholder value ``0.5``
        because they are not used to build a smooth layer.
        """

        def _role_values(role: str) -> List[Any]:
            values = []
            for level_idx, units in enumerate(levels):
                if activation_funcs[role][level_idx] == "smooth":
                    values.append(rng.uniform(0.0, 1.0, int(units)).astype(np.float32).tolist())
                else:
                    values.append(0.5)
            return values

        if activation_funcs.get("actions") == "smooth":
            action_values = rng.uniform(0.0, 1.0, int(action_units)).astype(np.float32).tolist()
            actions = action_values[0] if int(action_units) == 1 else action_values
        else:
            actions = 0.5

        return {
            "perception": _role_values("perception"),
            "reference": _role_values("reference"),
            "output": _role_values("output"),
            "actions": actions,
        }

    def __init__(
        self,
        env_name: str,
        levels: List[int],
        activation_funcs: Union[str, List[str], Dict[str, Any]] = "linear",
        weight_types: Union[str, List[str]] = "float",
        fixed_weights: Optional[Set[str]] = None,
        fixed_levels: Optional[Set[int]] = None,
        obs_connection_level: int = 0,
        random_seed: Optional[int] = None,
        smooth_factors: Optional[Union[float, Dict[str, Any]]] = None,
        reference_values: Optional[List[float]] = None,
        evolve_references: bool = False,
        top_reference_weight_init: str = "ones",
        top_level_obs_indices: Optional[List[int]] = None,
        zerolevel_inputs_indexes: Optional[List[int]] = None,
    ):
        """
        Initialize a DHPCTIndividual.
        
        Args:
            env_name: Gymnasium environment identifier (e.g., 'CartPole-v1')
            levels: Number of units per level, bottom to top (e.g., [4, 3, 2])
            activation_funcs: Activation function(s). Accepts:
                - str: single activation applied to all function types and levels
                  (e.g., "linear")
                - list[str]: per-level activation applied to all function types
                  (e.g., ["linear", "smooth", "linear"])
                - dict: per-function-type configuration with keys "perception",
                  "reference", "output" (each list[str] per level) and "actions"
                  (scalar str). Valid values: any Keras activation string,
                  "smooth" for ExponentialSmoothLayer, or
                  "sigmoid" for SigmoidLayer.
                Bare string/list shorthand is expanded to full dict form
                internally.
            weight_types: Weight type(s) - 'float', 'boolean', or 'ternary'
            fixed_weights: Set of layer names that should not mutate
            fixed_levels: Set of level indices that should not mutate
            obs_connection_level: Which level receives environment observations (default: 0)
            random_seed: Seed for reproducible weight initialization
            smooth_factors: Smooth factor(s) for ExponentialSmoothLayer when
                activation is "smooth". Accepts:
                - None: smooth layers initialize with random per-unit factors in [0, 1)
                - float: single value applied to all function types and levels
                - dict: per-function-type configuration with keys "perception",
                  "reference", "output" (each list[float] per level) and
                  "actions" (scalar float).
            reference_values: Initial values for the top-level reference input.
                If None, values are randomly initialized in ``[-1, 1]``.
                Must have length equal to ``levels[-1]`` (the top-level unit count).
            evolve_references: If True, reference_values are treated as
                evolvable parameters subject to mutation.
            top_reference_weight_init: Deprecated compatibility argument. Top-level
                reference weights (ReferencesInput -> RL top layer) are always
                fixed at 1.0 and are not evolved.
            top_level_obs_indices: Optional list of observation indices, one per
                top-level perception unit. When provided, each top-level perception
                unit has a single one-to-one connection to the observation at the
                specified index (instead of connecting to the level below).
                Length must equal levels[-1]. Indices must be valid for the
                environment's observation space.
            zerolevel_inputs_indexes: Optional list of observation indices that
                level-0 perception units should connect to.  Only valid when
                ``top_level_obs_indices`` is also provided and there are at
                least two levels.  When set, level-0 perception receives a gathered subset of
                observations at these indices via a fully-connected Dense layer
                instead of the full observation vector.
        
        Raises:
            ValueError: If levels is empty or configuration is invalid
            EnvironmentError: If environment cannot be created
        """
        # Validation
        if not levels or len(levels) == 0:
            raise ValueError("levels must have at least one element")
        if any(l < 1 for l in levels):
            raise ValueError("All level sizes must be >= 1")
        
        # Store parameters
        self.env_name = env_name
        self.levels = levels
        self.obs_connection_level = obs_connection_level
        self.top_level_obs_indices = top_level_obs_indices
        # Ignore zerolevel_inputs_indexes when there is only one level
        self.zerolevel_inputs_indexes = zerolevel_inputs_indexes if len(levels) > 1 else None
        # Filled by compile(): the effective observation indices feeding PL00.
        # When top_level_obs_indices is set, those dimensions are excluded.
        self.level0_observation_indices = None
        self.random_seed = random_seed
        # Keep genome initialization and rollout evaluation seeds distinct.
        # Saved configs restore evaluation_seed for deterministic replay.
        self.evaluation_seed = None
        self._smooth_factors_provided = smooth_factors is not None

        # Validate environment early so action dimensions are available for
        # random per-unit smooth-factor initialization.
        try:
            test_env = gym.make(env_name)
            self.env_properties = {
                'observation_space': str(test_env.observation_space),
                'action_space': str(test_env.action_space),
                'observation_shape': test_env.observation_space.shape,
                'action_shape': test_env.action_space.shape if hasattr(test_env.action_space, 'shape') else (test_env.action_space.n,),
            }
            test_env.close()
        except Exception as e:
            raise EnvironmentError(f"Failed to create environment '{env_name}': {e}")

        if top_reference_weight_init not in {"ones", "weight_type"}:
            raise ValueError(
                "top_reference_weight_init must be 'ones' or 'weight_type'"
            )
        # Retain the attribute for config/backward compatibility, but top-level
        # reference input gains are invariant: ReferencesInput values are the
        # set-points and must reach the top reference comparator unchanged.
        self.top_reference_weight_init = "ones"
        
        # Handle activation functions — always stored as full dict. Top-level
        # reference signals are external set-points and must pass through
        # linearly; lower-level references can still use configured activations.
        self.activation_funcs = self._expand_activation_funcs(activation_funcs, len(levels))
        self.activation_funcs["reference"][-1] = "linear"
        if top_level_obs_indices is not None:
            # Direct top-level observation pathways are literal environment
            # perceptions: keep them raw so top-level comparator error reflects
            # the selected observation rather than an evolvable/smoothed mapping.
            self.activation_funcs["perception"][-1] = "linear"
        
        # Handle smooth factors — always stored as full dict. When the caller
        # does not provide them, initialize each active smooth unit randomly
        # rather than forcing every alpha to 0.5.
        if smooth_factors is None:
            action_shape = self.env_properties['action_shape']
            action_units = action_shape[0] if len(action_shape) > 0 else 1
            smooth_seed = (
                None
                if random_seed is None
                else np.random.SeedSequence([int(random_seed), 0x51A7])
            )
            smooth_rng = np.random.default_rng(smooth_seed)
            self.smooth_factors = self._random_smooth_factors(
                self.levels, self.activation_funcs, int(action_units), smooth_rng
            )
        else:
            self.smooth_factors = self._expand_smooth_factors(smooth_factors, self.activation_funcs, len(levels))
        
        # Handle weight types
        if isinstance(weight_types, str):
            self.weight_types = [weight_types] * len(levels)
        else:
            if len(weight_types) != len(levels):
                raise ValueError(f"weight_types length ({len(weight_types)}) must match levels length ({len(levels)})")
            self.weight_types = weight_types
        
        # Validate obs_connection_level
        if obs_connection_level >= len(levels):
            raise ValueError(f"obs_connection_level ({obs_connection_level}) must be < len(levels) ({len(levels)})")
        
        # Validate top_level_obs_indices and zerolevel_inputs_indexes
        if top_level_obs_indices is not None:
            if len(top_level_obs_indices) != levels[-1]:
                raise ValueError(
                    f"top_level_obs_indices length ({len(top_level_obs_indices)}) "
                    f"must equal top-level units ({levels[-1]})"
                )
            try:
                test_env = gym.make(env_name)
                obs_size = test_env.observation_space.shape[0] if hasattr(test_env.observation_space, 'shape') else test_env.observation_space.n
                test_env.close()
                for idx in top_level_obs_indices:
                    if idx < 0 or idx >= obs_size:
                        raise ValueError(
                            f"top_level_obs_indices contains invalid index {idx}: "
                            f"must be in [0, {obs_size - 1}] for observation space size {obs_size}"
                        )
            except ValueError:
                raise
            except Exception:
                pass
        
        if self.zerolevel_inputs_indexes is not None:
            if top_level_obs_indices is None:
                raise ValueError(
                    "zerolevel_inputs_indexes is only valid when "
                    "top_level_obs_indices is also provided"
                )
            try:
                test_env = gym.make(env_name)
                obs_size = test_env.observation_space.shape[0] if hasattr(test_env.observation_space, 'shape') else test_env.observation_space.n
                test_env.close()
                for idx in self.zerolevel_inputs_indexes:
                    if idx < 0 or idx >= obs_size:
                        raise ValueError(
                            f"zerolevel_inputs_indexes contains invalid index {idx}: "
                            f"must be in [0, {obs_size - 1}] for observation space size {obs_size}"
                        )
            except ValueError:
                raise
            except Exception:
                pass
        
        # Initialize state
        self.fixed_weights = fixed_weights.copy() if fixed_weights is not None else set()
        self.fixed_weights.add(f"RL{len(self.levels) - 1:02d}")
        if self.top_level_obs_indices is not None:
            self.fixed_weights.add(f"PL{len(self.levels) - 1:02d}")
        self.fixed_levels = fixed_levels if fixed_levels is not None else set()
        self.evolve_references = evolve_references
        self.model = None
        self.fitness = None
        self.fitness_method = None
        self.fitness_source = None
        self.fitness_observation_indices = None
        self.fitness_targets = None
        self.fitness_kwargs = {}
        self.weights = {}
        self.history = None
        self.run_steps = 0
        self.total_reward = 0.0
        self.last_reward = None
        self.success = None
        
        # Handle reference values
        top_level_units = self.levels[-1]
        if reference_values is not None:
            if len(reference_values) != top_level_units:
                raise ValueError(
                    f"reference_values length ({len(reference_values)}) must match "
                    f"top-level units ({top_level_units})"
                )
            self.reference_values = np.array(reference_values, dtype=np.float32)
        else:
            rng = np.random.default_rng(random_seed)
            self.reference_values = rng.uniform(-1.0, 1.0, top_level_units).astype(np.float32)



