def _repr_impl(self):
    """Implementation of __repr__ method."""
    compiled_status = "compiled" if self.model is not None else "uncompiled"
    if self.fitness is not None:
        if isinstance(self.fitness, (int, float, np.floating)):
            fitness_str = f", fitness={float(self.fitness):.2f}"
        elif hasattr(self.fitness, "values") and getattr(self.fitness, "valid", False):
            fitness_str = f", fitness={float(self.fitness.values[0]):.2f}"
        else:
            fitness_str = ""
    else:
        fitness_str = ""
    obs_level_str = f", obs_level={self.obs_connection_level}" if self.obs_connection_level != 0 else ""
    obs_indices_str = f", top_level_obs_indices={self.top_level_obs_indices}" if self.top_level_obs_indices is not None else ""
    zl_indices_str = f", zerolevel_inputs_indexes={self.zerolevel_inputs_indexes}" if self.zerolevel_inputs_indexes is not None else ""
    return f"DHPCTIndividual(env='{self.env_name}', levels={self.levels}, {compiled_status}{fitness_str}{obs_level_str}{obs_indices_str}{zl_indices_str})"

DHPCTIndividual.__repr__ = _repr_impl

