def _getstate_impl(self):
    """Pickle via portable DPCT config instead of serializing Keras model directly."""
    state = self.__dict__.copy()
    try:
        state["_pickle_config"] = self.config() if self.model is not None else None
    except Exception:
        state["_pickle_config"] = None
    state["model"] = None
    state["history"] = None
    return state


def _setstate_impl(self, state):
    """Restore a pickled individual, recompiling from config when available."""
    pickle_config = state.pop("_pickle_config", None)
    preserved_fitness = state.get("fitness", None)
    self.__dict__.update(state)
    if pickle_config is not None:
        restored = type(self).from_config(pickle_config)
        self.__dict__.update(restored.__dict__)
        self.fitness = preserved_fitness


DHPCTIndividual.__getstate__ = _getstate_impl
DHPCTIndividual.__setstate__ = _setstate_impl


