_PERCEPTION_TERNARY_FLOAT_ELSE_WEIGHT_TYPES = {
    "ternary_perceptions_float_else",
    "ternary_perception_float_else",
    "perception_ternary_float_else",
}


def _effective_weight_type_impl(self, weight_type: str, role: str = "") -> str:
    """Resolve role-aware weight-type aliases to concrete initializer/mutation types.

    ``ternary_perceptions_float_else`` means perception connection weights use
    ternary values while reference/output/action connection weights remain
    continuous floats.  The shorter singular aliases are accepted for
    convenience/backward compatibility with early experiments.
    """
    if weight_type in _PERCEPTION_TERNARY_FLOAT_ELSE_WEIGHT_TYPES:
        return "ternary" if role == "perception" else "float"
    return weight_type


DHPCTIndividual._effective_weight_type = _effective_weight_type_impl


def _get_weight_initializer_impl(self, weight_type: str):
    """Get weight initializer for given concrete weight type."""
    if weight_type == "float":
        return keras.initializers.RandomUniform(minval=-1.0, maxval=1.0)
    elif weight_type == "boolean":
        return keras.initializers.Constant(value=1.0)  # Will be converted to boolean later
    elif weight_type == "ternary":
        return keras.initializers.Constant(value=0.0)  # Will be converted to ternary later
    elif weight_type in _PERCEPTION_TERNARY_FLOAT_ELSE_WEIGHT_TYPES:
        # Default to the non-perception side when no role is supplied. Role-aware
        # call sites use _effective_weight_type(..., role=...) before calling
        # this method.
        return keras.initializers.RandomUniform(minval=-1.0, maxval=1.0)
    else:
        raise ValueError(f"Unknown weight type: {weight_type}")

DHPCTIndividual._get_weight_initializer = _get_weight_initializer_impl


