def _create_activated_dense_impl(
    self,
    input_tensor,
    units: int,
    activation: str,
    smooth_factor: float,
    name: str,
    weight_type_idx: int,
    weight_role: str = "perception",
):
    """Create a Dense layer with optional activation layer attachment."""
    # Get initializer based on role-aware weight type
    initializer = self._get_weight_initializer(
        self._effective_weight_type(self.weight_types[weight_type_idx], weight_role)
    )
    
    if activation == "smooth":
        # Create linear Dense layer
        dense = layers.Dense(
            units=units,
            activation="linear",
            name=name,
            kernel_initializer=initializer,
            use_bias=False,
        )(input_tensor)
        # Add ExponentialSmoothLayer
        smooth_layer = ExponentialSmoothLayer(
            smooth_factor=smooth_factor,
            name=f"{name}_smooth"
        )(dense)
        return smooth_layer
    elif activation == "sigmoid":
        # Create linear Dense layer
        dense = layers.Dense(
            units=units,
            activation="linear",
            name=name,
            kernel_initializer=initializer,
            use_bias=False,
        )(input_tensor)
        # Add SigmoidLayer
        sigmoid_layer = SigmoidLayer(name=f"{name}_sigmoid")(dense)
        return sigmoid_layer
    else:
        # Standard Keras activation
        return layers.Dense(
            units=units,
            activation=activation,
            name=name,
            kernel_initializer=initializer,
            use_bias=False,
        )(input_tensor)

DHPCTIndividual._create_activated_dense = _create_activated_dense_impl


