def _get_optimizer_instance_impl(self, optimizer_name: str, learning_rate: float):
    """Create optimizer instance for training.
    
    Args:
        optimizer_name: Name of optimizer ('adam', 'sgd', 'rmsprop', etc.)
        learning_rate: Learning rate for optimizer
        
    Returns:
        Keras optimizer instance
        
    Raises:
        ValueError: If optimizer name is not supported
    """
    optimizer_name = optimizer_name.lower()
    
    if optimizer_name == 'adam':
        return keras.optimizers.Adam(learning_rate=learning_rate)
    elif optimizer_name == 'sgd':
        return keras.optimizers.SGD(learning_rate=learning_rate)
    elif optimizer_name == 'rmsprop':
        return keras.optimizers.RMSprop(learning_rate=learning_rate)
    elif optimizer_name == 'adagrad':
        return keras.optimizers.Adagrad(learning_rate=learning_rate)
    else:
        raise ValueError(f"Unsupported optimizer: {optimizer_name}. Supported: adam, sgd, rmsprop, adagrad")

DHPCTIndividual._get_optimizer_instance = _get_optimizer_instance_impl

# %% ../nbs/00_individual.ipynb #15d864c6
def _compile_impl(self):
    """
    Build Keras Functional API model from hierarchy specification.
    
    Creates perception, reference, comparator, and output layers for each level
    following PCT principles. Initializes weights according to weight_types.
    
    If already compiled, allows recompilation by clearing the existing model.
    
    Raises:
        ValueError: If hierarchy specification is invalid
    """
    if self.model is not None:
        keras.backend.clear_session()
        self.model = None  # Allow recompilation
    num_levels = len(self.levels)
    
    # Set random seed for reproducibility
    if self.random_seed is not None:
        set_random_seed(self.random_seed)
    
    # Get environment dimensions
    obs_shape = self.env_properties['observation_shape']
    action_shape = self.env_properties['action_shape']
    obs_dim = obs_shape[0] if len(obs_shape) > 0 else 1
    action_dim = action_shape[0] if len(action_shape) > 0 else 1
    
    # Create input layers
    observations = layers.Input(shape=(obs_dim,), name='Observations')
    
    # Reference input dimension matches top-level unit count
    ref_dim = self.levels[-1]
    references_input = layers.Input(shape=(ref_dim,), name='ReferencesInput')
    
    # Storage for layer outputs
    perception_outputs = []
    reference_outputs = [None] * num_levels
    comparator_outputs = [None] * num_levels
    output_layer_outputs = [None] * num_levels
    
    def _effective_level0_observation_indices() -> Optional[List[int]]:
        """Return observation indices connected to level-0 perceptions.

        When the top level is wired directly to observations, those observation
        dimensions are removed from the bottom-level input so the same raw
        observation is not controlled independently at both hierarchy ends.
        """
        if num_levels == 1:
            return None

        if self.zerolevel_inputs_indexes is not None:
            candidate_indices = list(self.zerolevel_inputs_indexes)
        elif self.top_level_obs_indices is not None:
            candidate_indices = list(range(obs_dim))
        else:
            return None

        if self.top_level_obs_indices is not None:
            top_indices = set(int(idx) for idx in self.top_level_obs_indices)
            candidate_indices = [idx for idx in candidate_indices if int(idx) not in top_indices]

        if not candidate_indices:
            raise ValueError(
                "Level-0 observation inputs are empty after excluding "
                "top_level_obs_indices from the bottom-level perception input"
            )
        return candidate_indices

    level0_observation_indices = _effective_level0_observation_indices()
    self.level0_observation_indices = level0_observation_indices

    # === PASS 1: Build perception layers ===
    for level_idx, num_units in enumerate(self.levels):
        level_name = f"{level_idx:02d}"
        
        if level_idx == 0:
            # Level 0 connects to observations
            if self.top_level_obs_indices is not None and level_idx == num_levels - 1:
                # T024a: Single-level with direct observation connections
                gathered_obs = layers.Lambda(
                    lambda x: tf.gather(x, self.top_level_obs_indices, axis=1),
                    name=f"GatherObs{level_name}"
                )(observations)
                perception_layer = layers.Dense(
                    units=num_units,
                    activation="linear",
                    name=f"PL{level_name}",
                    kernel_initializer=keras.initializers.Identity(gain=1.0),
                    use_bias=False,
                    trainable=False,
                )(gathered_obs)
            elif level0_observation_indices is not None:
                # T024b / top-level direct observation: gather the effective
                # level-0 observation subset.  If top_level_obs_indices is set,
                # those dimensions are intentionally excluded from this bottom
                # input so they are controlled only by the direct top-level path.
                gathered_obs = layers.Lambda(
                    lambda x, idx=level0_observation_indices: tf.gather(x, idx, axis=1),
                    name=f"GatherObsL{level_name}"
                )(observations)
                perception_layer = self._create_activated_dense(
                    input_tensor=gathered_obs,
                    units=num_units,
                    activation=self.activation_funcs["perception"][level_idx],
                    smooth_factor=self.smooth_factors["perception"][level_idx],
                    name=f"PL{level_name}",
                    weight_type_idx=level_idx,
                    weight_role="perception"
                )
            else:
                # Standard observation connection
                perception_layer = self._create_activated_dense(
                    input_tensor=observations,
                    units=num_units,
                    activation=self.activation_funcs["perception"][level_idx],
                    smooth_factor=self.smooth_factors["perception"][level_idx],
                    name=f"PL{level_name}",
                    weight_type_idx=level_idx,
                    weight_role="perception"
                )
        elif level_idx == num_levels - 1 and self.top_level_obs_indices is not None:
            # T024a: Top level with direct observation connections
            gathered_obs = layers.Lambda(
                lambda x: tf.gather(x, self.top_level_obs_indices, axis=1),
                name=f"GatherObs{level_name}"
            )(observations)
            # Fixed one-to-one raw observation mapping. Do not allow this
            # path to evolve, add bias, or smooth/nonlinearly transform values;
            # otherwise top_level_comparator_error can be minimized by changing
            # the perception calibration instead of moving the environment state.
            perception_layer = layers.Dense(
                units=num_units,
                activation="linear",
                name=f"PL{level_name}",
                kernel_initializer=keras.initializers.Identity(gain=1.0),
                use_bias=False,
                trainable=False,
            )(gathered_obs)
        else:
            # Higher levels connect to lower level perception outputs
            prev_perception = perception_outputs[level_idx - 1]
            perception_layer = self._create_activated_dense(
                input_tensor=prev_perception,
                units=num_units,
                activation=self.activation_funcs["perception"][level_idx],
                smooth_factor=self.smooth_factors["perception"][level_idx],
                name=f"PL{level_name}",
                weight_type_idx=level_idx
            )
        
        perception_outputs.append(perception_layer)
    
    # === PASS 2: Build reference, comparator, and output layers ===
    for level_idx in reversed(range(num_levels)):
        level_name = f"{level_idx:02d}"
        num_units = self.levels[level_idx]
        
        # Reference layers
        if level_idx == num_levels - 1:
            # Top level connects to reference input with fixed unit gains. These
            # weights are intentionally not controlled by weight_type: top-level
            # reference values are external set-points and must pass through as-is.
            ref_initializer = keras.initializers.Ones()
            
            reference_layer = ElementWiseMultiplyLayer(
                units=num_units,
                weight_initializer=ref_initializer,
                name=f"RL{level_name}"
            )(references_input)
        else:
            # Lower levels connect to higher level outputs
            higher_output = output_layer_outputs[level_idx + 1]
            reference_layer = self._create_activated_dense(
                input_tensor=higher_output,
                units=num_units,
                activation=self.activation_funcs["reference"][level_idx],
                smooth_factor=self.smooth_factors["reference"][level_idx],
                name=f"RL{level_name}",
                weight_type_idx=level_idx,
                weight_role="reference"
            )
        
        reference_outputs[level_idx] = reference_layer
        
        # Comparator layers (error = reference - perception)
        comparator_layer = layers.Subtract(name=f"CL{level_name}")(
            [reference_outputs[level_idx], perception_outputs[level_idx]]
        )
        comparator_outputs[level_idx] = comparator_layer
        
        # Output layers (proportional control)
        output_layer = ElementWiseMultiplyLayer(
            units=num_units,
            weight_initializer=self._get_weight_initializer(
                self._effective_weight_type(self.weight_types[level_idx], "output")
            ),
            name=f"OL{level_name}"
        )(comparator_layer)
        
        # Apply activation if needed
        if self.activation_funcs["output"][level_idx] == "smooth":
            output_layer = ExponentialSmoothLayer(
                smooth_factor=self.smooth_factors["output"][level_idx],
                name=f"OL{level_name}_smooth"
            )(output_layer)
        elif self.activation_funcs["output"][level_idx] == "sigmoid":
            output_layer = SigmoidLayer(name=f"OL{level_name}_sigmoid")(output_layer)
        elif self.activation_funcs["output"][level_idx] != "linear":
            output_layer = layers.Activation(
                self.activation_funcs["output"][level_idx],
                name=f"OL{level_name}_activation"
            )(output_layer)
        
        output_layer_outputs[level_idx] = output_layer
    
    # Create action output from level 0 output
    actions = self._create_activated_dense(
        input_tensor=output_layer_outputs[0],
        units=action_dim,
        activation=self.activation_funcs["actions"],
        smooth_factor=self.smooth_factors["actions"],
        name="Actions",
        weight_type_idx=0,
        weight_role="actions"
    )
    
    # Create error output (concatenate all comparator outputs)
    if len(comparator_outputs) == 1:
        errors = layers.Lambda(lambda x: x, name="Errors")(comparator_outputs[0])
    else:
        errors = layers.Concatenate(name="Errors")(comparator_outputs)
    
    # Create the model
    self.model = keras.Model(
        inputs=[observations, references_input],
        outputs=[actions, errors],
        name="DHPCTIndividual"
    )
    
    # Store weights for easy access
    self._store_weights()

DHPCTIndividual.compile = _compile_impl


# %% ../nbs/00_individual.ipynb #1e140989
def _store_weights_impl(self):
    """Store current model weights in self.weights dictionary."""
    if self.model is None:
        return
    
    self.weights = {}
    for layer in self.model.layers:
        if hasattr(layer, 'get_weights') and len(layer.get_weights()) > 0:
            weights = layer.get_weights()
            if len(weights) > 0:
                self.weights[layer.name] = weights[0].copy()
            if len(weights) > 1:  # Bias weights
                self.weights[f"{layer.name}_bias"] = weights[1].copy()

DHPCTIndividual._store_weights = _store_weights_impl

# %% ../nbs/00_individual.ipynb #fa48214b
def _reset_smooth_layers_impl(self):
    """Reset state in all ExponentialSmoothLayer instances."""
    if self.model is None:
        return
    
    for layer in self.model.layers:
        if isinstance(layer, ExponentialSmoothLayer):
            layer.reset_state()

DHPCTIndividual._reset_smooth_layers = _reset_smooth_layers_impl

