def _map_action(raw_action: np.ndarray, action_space) -> "Union[int, np.ndarray]":
    """Map raw model output to a valid environment action.

    Args:
        raw_action: Raw action array from the model's Actions output
            (1-D, already stripped of the batch dimension).
        action_space: The Gymnasium action space of the target
            environment (``env.action_space``).

    Returns:
        An ``int`` for discrete spaces or a clipped ``np.ndarray`` for
        continuous spaces.
    """
    if hasattr(action_space, 'n'):  # Discrete action space
        raw_values = np.asarray(raw_action).reshape(-1)
        if raw_values.size == 1:
            # Scalar discrete policies preserve PCT's signed control signal.
            # Binary spaces use sign: <= 0 -> 0, > 0 -> 1.
            # Ternary directional spaces such as MountainCar-v0/Acrobot-v1
            # use sign with zero as neutral: < 0 -> 0, == 0 -> 1, > 0 -> 2.
            scalar_action = float(raw_values[0])
            if getattr(action_space, 'n', None) == 3:
                if scalar_action < 0.0:
                    return 0
                if scalar_action > 0.0:
                    return 2
                return 1
            return int(scalar_action > 0.0)
        else:
            # Multi-output discrete policies select the highest-scoring action.
            return int(np.argmax(raw_values))
    else:  # Continuous action space
        # Clip action to valid range
        return np.clip(raw_action, action_space.low, action_space.high)

DHPCTIndividual.map_action = staticmethod(_map_action)

# %% ../nbs/00_individual.ipynb #630edc47
def _resolve_fitness_error_values(
    *,
    fitness_source: str,
    errors_list: List[np.ndarray],
    observation_values_list: List[np.ndarray],
    fitness_observation_indices: Optional[List[int]],
    fitness_targets: Optional[List[float]],
    pad_to_steps: Optional[int] = None,
    terminal_observation_values: Optional[np.ndarray] = None,
    top_level_units: Optional[int] = None,
) -> np.ndarray:
    """Return flattened errors from comparator outputs or observation deltas.

    When ``pad_to_steps`` is provided and the rollout ended before that
    horizon, the returned error array is padded to a fixed number of time
    steps.  This keeps RMS/MAE fitness comparable between early-terminated
    and full-horizon rollouts.  Observation-source fitness pads with the
    terminal observation when available (e.g. MountainCarContinuous reaching
    the goal); comparator-error fitness pads with the last observed comparator
    error because no comparator output exists for the post-step terminal
    observation.
    """
    requested_steps = int(pad_to_steps) if pad_to_steps is not None else None
    if requested_steps is not None and requested_steps < 0:
        raise ValueError(f"pad_to_steps must be >= 0, got {requested_steps}")

    if fitness_source in {"comparator_error", "top_level_comparator_error"}:
        error_rows = np.asarray(errors_list, dtype=np.float32)
        if error_rows.size == 0:
            return np.array([], dtype=np.float32)
        if error_rows.ndim == 1:
            error_rows = error_rows.reshape(-1, 1)
        if fitness_source == "top_level_comparator_error":
            if top_level_units is None:
                raise ValueError("top_level_units is required for fitness_source='top_level_comparator_error'")
            top_level_units = int(top_level_units)
            if top_level_units <= 0:
                raise ValueError(f"top_level_units must be > 0, got {top_level_units}")
            if top_level_units > error_rows.shape[1]:
                raise ValueError(
                    f"top_level_units ({top_level_units}) cannot exceed comparator error width "
                    f"({error_rows.shape[1]})"
                )
            error_rows = error_rows[:, -top_level_units:]
        if requested_steps is not None and error_rows.shape[0] < requested_steps:
            pad_count = requested_steps - error_rows.shape[0]
            pad_rows = np.repeat(error_rows[-1:, :], pad_count, axis=0)
            error_rows = np.vstack([error_rows, pad_rows])
        return error_rows.reshape(-1)

    all_observations = np.asarray(observation_values_list, dtype=np.float32)
    if all_observations.ndim == 1:
        all_observations = all_observations.reshape(-1, 1)

    if all_observations.size == 0:
        selected_observations = np.empty((0, 0), dtype=np.float32)
    elif fitness_observation_indices is None:
        selected_observations = all_observations
    else:
        obs_dim = all_observations.shape[1]
        invalid_indices = [idx for idx in fitness_observation_indices if idx < 0 or idx >= obs_dim]
        if invalid_indices:
            raise ValueError(
                f"fitness_observation_indices must be within [0, {obs_dim - 1}], "
                f"got {invalid_indices}"
            )
        selected_observations = all_observations[:, fitness_observation_indices]

    if selected_observations.ndim == 1:
        selected_observations = selected_observations.reshape(-1, 1)

    feature_count = selected_observations.shape[1]
    if fitness_targets is None:
        targets = np.zeros(feature_count, dtype=np.float32)
    else:
        if len(fitness_targets) != feature_count:
            raise ValueError(
                f"fitness_targets length ({len(fitness_targets)}) must match selected "
                f"observation count ({feature_count})"
            )
        targets = np.asarray(fitness_targets, dtype=np.float32)

    error_rows = selected_observations - targets
    if requested_steps is not None and error_rows.shape[0] < requested_steps:
        pad_count = requested_steps - error_rows.shape[0]
        if terminal_observation_values is not None:
            terminal_observation = np.asarray(terminal_observation_values, dtype=np.float32).reshape(1, -1)
            if fitness_observation_indices is None:
                selected_terminal = terminal_observation
            else:
                obs_dim = terminal_observation.shape[1]
                invalid_indices = [idx for idx in fitness_observation_indices if idx < 0 or idx >= obs_dim]
                if invalid_indices:
                    raise ValueError(
                        f"fitness_observation_indices must be within [0, {obs_dim - 1}], "
                        f"got {invalid_indices}"
                    )
                selected_terminal = terminal_observation[:, fitness_observation_indices]
            pad_error = selected_terminal - targets
        elif error_rows.shape[0] > 0:
            pad_error = error_rows[-1:, :]
        else:
            pad_error = np.zeros((1, feature_count), dtype=np.float32)
        pad_rows = np.repeat(pad_error, pad_count, axis=0)
        error_rows = np.vstack([error_rows, pad_rows])

    return error_rows.reshape(-1)


def _apply_failure_penalty(
    base_error: float,
    *,
    steps_completed: int,
    requested_steps: int,
    failure_penalty: float,
) -> float:
    """Return base error plus an incomplete-rollout penalty."""
    if requested_steps <= 0:
        raise ValueError(f"requested_steps must be > 0, got {requested_steps}")

    clamped_steps_completed = max(0, min(int(steps_completed), int(requested_steps)))
    completion_ratio = clamped_steps_completed / float(requested_steps)
    return float(base_error) + float(failure_penalty) * (1.0 - completion_ratio)


_BUILT_IN_FITNESS_METHODS = {
    "cumulative_reward",
    "evaluation_steps",
    "rms",
    "mae",
    "rms_adjusted",
    "adjusted_rms",
    "mae_adjusted",
    "adjusted_mae",
}


def _available_environment_fitness_methods(env_name: str) -> List[str]:
    """Return registered dpct-env fitness method names for an environment."""
    try:
        from dpct_env.fitness import get_fitness_functions
    except ImportError:
        return []
    try:
        return sorted(get_fitness_functions(env_name).keys())
    except Exception:
        return []


def _resolve_environment_fitness_function(fitness_method: str, env_name: str, fitness_kwargs: Optional[dict] = None):
    """Resolve an environment-specific fitness function via dpct-env.

    dpct-env owns the registry and all environment-specific scoring logic.
    This adapter keeps core dpct generic while tolerating both the current
    ``create_fitness_function(name, env_name)`` API and a future configurable
    ``create_fitness_function(name, env_name, **kwargs)`` API.
    """
    fitness_kwargs = dict(fitness_kwargs or {})
    try:
        from dpct_env.fitness import create_fitness_function, get_fitness_functions
    except ImportError as exc:
        raise ValueError(
            f"Unknown fitness_method '{fitness_method}'. Built-in methods: {sorted(_BUILT_IN_FITNESS_METHODS)}. "
            "Environment-specific fitness methods require the 'dpct-env' package."
        ) from exc

    try:
        try:
            return create_fitness_function(fitness_method, env_name=env_name, **fitness_kwargs)
        except TypeError as exc:
            if not fitness_kwargs:
                raise
            try:
                fitness_fn = create_fitness_function(fitness_method, env_name=env_name)
                return fitness_fn.__class__(**fitness_kwargs)
            except Exception:
                raise exc
    except KeyError as exc:
        available = sorted(get_fitness_functions(env_name).keys())
        raise ValueError(
            f"Unknown fitness_method '{fitness_method}' for env_name='{env_name}'. "
            f"Built-in methods: {sorted(_BUILT_IN_FITNESS_METHODS)}. "
            f"Registered environment-specific methods: {available}."
        ) from exc


def _run(
    self,
    steps: int = 500,
    early_termination: bool = False,
    render: bool = False,
    render_mode: Optional[str] = None,
    frame_callback: Optional[Callable[[np.ndarray], None]] = None,
    verbose: bool = False,
    train: bool = False,
    learning_rate: float = 0.01,
    optimizer='adam',
    train_every_n_steps: int = 10,
    error_weight_coefficients: Optional[List[float]] = None,
    fitness_method: Optional[str] = None,
    fitness_source: Optional[str] = None,
    fitness_observation_indices: Optional[List[int]] = None,
    fitness_targets: Optional[List[float]] = None,
    fitness_kwargs: Optional[dict] = None,
    record_history: bool = False,
    failure_penalty: float = 1.0,
):
    """Run individual in environment for specified number of steps.

    Args:
        steps: Maximum number of steps to run
        early_termination: Stop when environment terminates if True
        render: Render environment during execution
        render_mode: Optional Gymnasium render mode override (e.g. 'rgb_array')
        frame_callback: Optional callback receiving each rendered frame
        verbose: Print step-by-step information
        train: Enable online learning during execution
        learning_rate: Learning rate for online training
        optimizer: Optimizer name or optimizer instance for online training
        train_every_n_steps: Perform training update every N steps
        error_weight_coefficients: Optional per-level coefficients for error weighting (reserved)
        fitness_method: Method for fitness calculation ('cumulative_reward', 'evaluation_steps',
            'rms', 'mae', 'rms_adjusted'/'adjusted_rms', 'mae_adjusted'/'adjusted_mae').
            If None, reuse ``self.fitness_method`` from saved/evaluated metadata or
            fall back to ``'cumulative_reward'``.
        fitness_source: Source used by error fitness methods ('comparator_error',
            'top_level_comparator_error', or 'observation'). If None, reuse
            ``self.fitness_source`` or fall back to ``'comparator_error'``.
        fitness_observation_indices: Optional subset of observation indices used when fitness_source='observation'.
            If None, reuse ``self.fitness_observation_indices`` when present.
        fitness_targets: Optional per-index targets used when fitness_source='observation' (defaults to zeros).
            If None, reuse ``self.fitness_targets`` when present.
        fitness_kwargs: Optional configuration forwarded to environment-specific fitness factories
        record_history: Record detailed execution history for visualization
        failure_penalty: Penalty scale for adjusted error methods when rollout is incomplete

    Returns:
        Fitness score (higher is better for cumulative_reward/evaluation_steps, lower error is better for error methods)
    """
    if self.model is None:
        raise RuntimeError("Individual must be compiled before running")

    # ``fitness_*`` arguments are per-run overrides.  When omitted, prefer
    # metadata restored from ``from_config()`` (or from a prior evaluation) so
    # ``DHPCTIndividual.from_config(cfg).run()`` replays the saved objective.
    # Fall back to the historical defaults for fresh individuals.
    if fitness_method is None:
        fitness_method = self.fitness_method or "cumulative_reward"
    if fitness_source is None:
        fitness_source = self.fitness_source or "comparator_error"
    if fitness_observation_indices is None:
        fitness_observation_indices = self.fitness_observation_indices
    if fitness_targets is None:
        fitness_targets = self.fitness_targets
    
    if error_weight_coefficients is not None:
        num_levels = len(self.levels)
        if len(error_weight_coefficients) != num_levels:
            raise ValueError(
                f"error_weight_coefficients length ({len(error_weight_coefficients)}) "
                f"must match number of levels ({num_levels})"
            )

    if fitness_source not in {"comparator_error", "top_level_comparator_error", "observation"}:
        raise ValueError(
            "fitness_source must be 'comparator_error', 'top_level_comparator_error', "
            f"or 'observation', got '{fitness_source}'"
        )
    
    adjusted_error_methods = {"rms_adjusted", "adjusted_rms", "mae_adjusted", "adjusted_mae"}
    if fitness_method in adjusted_error_methods and steps <= 0:
        raise ValueError(f"requested_steps must be > 0, got {steps}")

    # Create environment
    import gymnasium as gym
    effective_render_mode = render_mode if render_mode is not None else ("human" if render else None)
    env = gym.make(self.env_name, render_mode=effective_render_mode)
    capture_frames = effective_render_mode == "rgb_array" or frame_callback is not None
    self.last_environment_history = None
    
    # Reset smooth layers at episode start
    self._reset_smooth_layers()
    
    # Initialize tracking variables
    total_reward = 0.0
    last_reward = None
    self.last_reward = None
    errors_list = []
    observation_values_list = []
    action_values_list = []
    info_list = []
    step_count = 0
    rollout_terminated = False
    terminal_observation_values = None
    
    # Setup online training if requested
    if train:
        import tensorflow as tf
        opt_instance = self._get_optimizer_instance(optimizer, learning_rate)
        self.model.compile(optimizer=opt_instance, loss='mse')
    
    # Always keep a lightweight execution history so environment-specific
    # processors can determine task success even when detailed layer history is
    # not requested.  Layer activations are captured only for record_history.
    from dpct_run.individual_utils import ExecutionHistory
    execution_history = ExecutionHistory()
    self.history = execution_history if record_history else None
    history_model = None
    activation_layer_names = []
    if record_history:
        # Build one combined model that returns actions/errors plus intermediate
        # layer activations in a single forward pass.  This is important for
        # stateful layers such as ExponentialSmoothLayer: calling self.model and
        # then a separate activation model would advance smooth-layer state twice
        # per environment step and change the controller's behaviour.
        intermediate_outputs = {}
        for layer in self.model.layers:
            if any(layer.name.startswith(prefix) for prefix in ('PL', 'RL', 'CL', 'OL')):
                intermediate_outputs[layer.name] = layer.output
        if intermediate_outputs:
            activation_layer_names = list(intermediate_outputs.keys())
            history_model = keras.Model(
                inputs=self.model.input,
                outputs=[self.model.output[0], self.model.output[1], *intermediate_outputs.values()]
            )
    
    try:
        # Reset environment. When random_seed is set we seed the environment for deterministic runs.
        reset_kwargs = {}
        if self.random_seed is not None:
            reset_kwargs['seed'] = int(self.random_seed)
        observation, info = env.reset(**reset_kwargs)
        observation = np.array(observation, dtype=np.float32).reshape(1, -1)

        if capture_frames:
            frame = env.render()
            if frame_callback is not None:
                frame_callback(frame)
        
        for step in range(steps):
            # Prepare reference input (zeros or configured values)
            ref_input = self.reference_values.reshape(1, -1)
            
            # Get model prediction, and optionally layer activations, with one
            # forward pass so history recording is observational only.
            activation_tensors = []
            if record_history and history_model is not None:
                model_outputs = history_model([observation, ref_input])
                action_pred, error_pred = model_outputs[0], model_outputs[1]
                activation_tensors = model_outputs[2:]
            else:
                action_pred, error_pred = self.model([observation, ref_input])
            
            action_values = action_pred.numpy()[0]
            error_values = error_pred.numpy()[0]
            observation_values = observation[0]
            
            # Map action to environment format
            raw_action = action_values  # Remove batch dimension
            env_action = self.map_action(raw_action, env.action_space)
            
            # Take step in environment
            next_observation, reward, terminated, truncated, info = env.step(env_action)
            done = terminated or truncated

            if capture_frames:
                frame = env.render()
                if frame_callback is not None:
                    frame_callback(frame)
            
            # Update tracking
            reward_value = float(reward)
            total_reward += reward_value
            last_reward = reward_value
            self.last_reward = reward_value
            errors_list.append(error_values)
            observation_values_list.append(observation_values)
            action_values_list.append(env_action)
            info_list.append(info)
            step_count += 1
            
            # Record lightweight execution history for task-success processors;
            # include layer activations only when detailed history is requested.
            layer_activations = None
            if record_history and activation_tensors:
                if not isinstance(activation_tensors, list):
                    activation_tensors = [activation_tensors]
                layer_activations = {
                    name: act.numpy()[0]
                    for name, act in zip(activation_layer_names, activation_tensors)
                }
            execution_history.add_step(
                observation=np.array(next_observation, dtype=np.float32),
                action=env_action,
                reward=reward,
                error=error_values,
                terminated=terminated,
                truncated=truncated,
                layer_activations=layer_activations,
                pre_observation=observation_values,
            )
            
            # Verbose output: show both sides of the transition.  The model's
            # perception/action are computed from current_obs; task success is
            # based on next_obs plus the environment termination flags.
            if verbose:
                print(f"Step {step}: current_obs={observation_values}")
                print(f"next_obs={np.array(next_observation, dtype=np.float32)}")
                print(f"error_pred={error_values}")
                print(f"action_pred={action_values}")
                print(f"reward={reward}, terminated={terminated}, truncated={truncated}, done={done}")
            
            # Training update
            if train and step % train_every_n_steps == 0:
                # Simple training: minimize prediction error
                target_error = np.zeros_like(error_pred.numpy())
                with tf.GradientTape() as tape:
                    _, pred_error = self.model([observation, ref_input])
                    loss = tf.reduce_mean(tf.square(pred_error - target_error))
                
                # Only compute gradients for weights involved in error computation (exclude Actions layer)
                trainable_weights_for_error = [
                    w for w in self.model.trainable_weights 
                    if not any(layer_name in w.name for layer_name in ['Actions'])
                ]
                gradients = tape.gradient(loss, trainable_weights_for_error)
                grad_var_pairs = [
                    (g, v) for g, v in zip(gradients, trainable_weights_for_error)
                    if g is not None
                ]
                if grad_var_pairs:
                    opt_instance.apply_gradients(grad_var_pairs)
            
            # Handle episode end without stepping a terminated environment.
            if done:
                terminal_observation_values = np.array(next_observation, dtype=np.float32)
                if early_termination:
                    if step_count < steps:
                        rollout_terminated = terminated
                    break
                observation, _ = env.reset(**reset_kwargs)
                observation = np.array(observation, dtype=np.float32).reshape(1, -1)
            else:
                observation = np.array(next_observation, dtype=np.float32).reshape(1, -1)
        
    except Exception as e:
        env.close()
        raise EnvironmentError(f"Error during environment execution: {e}")
    finally:
        self.last_environment_history = execution_history
        env.close()

    # Error-based fitness should be comparable across early-terminated and
    # full-horizon rollouts.  If execution stops early, pad the error trace to
    # the requested horizon instead of changing the RMS/MAE denominator.
    fixed_error_horizon = int(steps) if early_termination and step_count < int(steps) else None

    # Calculate fitness based on method
    if fitness_method == "cumulative_reward":
        fitness = total_reward
    elif fitness_method == "evaluation_steps":
        fitness = float(step_count)
    elif fitness_method in {"rms", "rms_adjusted", "adjusted_rms"}:
        from dpct_run.individual_utils import calculate_rms_error

        base_error = calculate_rms_error(_resolve_fitness_error_values(
            fitness_source=fitness_source,
            errors_list=errors_list,
            observation_values_list=observation_values_list,
            fitness_observation_indices=fitness_observation_indices,
            fitness_targets=fitness_targets,
            pad_to_steps=fixed_error_horizon,
            terminal_observation_values=terminal_observation_values,
            top_level_units=self.levels[-1],
        ))  # Positive, lower is better
        if fitness_method in {"rms_adjusted", "adjusted_rms"}:
            fitness = _apply_failure_penalty(
                base_error,
                steps_completed=step_count,
                requested_steps=int(steps),
                failure_penalty=failure_penalty,
            )
            fitness_method = "rms_adjusted"
        else:
            fitness = base_error
    elif fitness_method in {"mae", "mae_adjusted", "adjusted_mae"}:
        from dpct_run.individual_utils import calculate_mae_error

        base_error = calculate_mae_error(_resolve_fitness_error_values(
            fitness_source=fitness_source,
            errors_list=errors_list,
            observation_values_list=observation_values_list,
            fitness_observation_indices=fitness_observation_indices,
            fitness_targets=fitness_targets,
            pad_to_steps=fixed_error_horizon,
            terminal_observation_values=terminal_observation_values,
            top_level_units=self.levels[-1],
        ))  # Positive, lower is better
        if fitness_method in {"mae_adjusted", "adjusted_mae"}:
            fitness = _apply_failure_penalty(
                base_error,
                steps_completed=step_count,
                requested_steps=int(steps),
                failure_penalty=failure_penalty,
            )
            fitness_method = "mae_adjusted"
        else:
            fitness = base_error
    else:
        fitness_fn = _resolve_environment_fitness_function(
            fitness_method,
            env_name=self.env_name,
            fitness_kwargs=fitness_kwargs,
        )
        fitness = float(fitness_fn(
            observation_history=np.asarray(observation_values_list),
            action_history=np.asarray(action_values_list),
            info_history=info_list,
        ))
    
    # Update instance variables
    self.fitness = fitness
    self.fitness_method = fitness_method
    self.fitness_source = fitness_source
    self.fitness_observation_indices = fitness_observation_indices
    self.fitness_targets = fitness_targets
    self.fitness_kwargs = dict(fitness_kwargs or {})

    self.run_steps = step_count
    self.total_reward = float(total_reward)
    self.last_reward = last_reward

    # Generic success: completed the full horizon without early termination.
    generic_success = step_count >= steps and not rollout_terminated

    # Check for environment-specific task success override.
    # Some environments (e.g. MountainCarContinuous-v0) have a task success
    # condition that causes early termination (position >= 0.45 and velocity >= 0).
    # For these, the generic definition would incorrectly mark successful
    # episodes as failures. Ask dpct-env's processor factory for the selected
    # environment so core dpct does not hardcode environment-specific imports.
    task_success = None
    try:
        from dpct_env.processors import create_environment_results_processor
        processor = create_environment_results_processor(self.env_name)
        task_success = processor.get_task_success(
            individual=self,
            history=self.last_environment_history,
            env_name=self.env_name,
        )
    except (ImportError, AttributeError):
        pass  # dpct-env not installed or processor lacks override; use generic success only

    if task_success is not None:
        self.success = task_success
    else:
        self.success = generic_success

    # Store updated weights
    self._store_weights()

    return fitness

DHPCTIndividual.run = _run


# %% ../nbs/00_individual.ipynb #25c72754
def _evaluate(
    self,
    nevals: int = 1,
    aggregate: str = "mean",
    evaluation_seed: Optional[int] = None,
    **run_kwargs,
) -> float:
    """Evaluate fitness across multiple runs and aggregate the result.

    Args:
        nevals: Number of evaluations to run.
        aggregate: Aggregation method ('mean', 'max', 'min', 'median').
        evaluation_seed: Optional environment seed. When omitted, use the
            seed restored from saved metadata, falling back to the genome seed
            for older configs.
        **run_kwargs: Additional keyword arguments forwarded to ``run``.

    Returns:
        Aggregated fitness score.

    Raises:
        ValueError: If ``nevals`` or ``aggregate`` are invalid.
    """
    if nevals < 1:
        raise ValueError(f"nevals must be >= 1, got {nevals}")

    valid_aggregates = {"mean", "max", "min", "median"}
    if aggregate not in valid_aggregates:
        raise ValueError(
            f"aggregate must be one of {sorted(valid_aggregates)}, got '{aggregate}'"
        )

    if run_kwargs.get("fitness_method") == "adjusted_rms":
        run_kwargs = {**run_kwargs, "fitness_method": "rms_adjusted"}
    elif run_kwargs.get("fitness_method") == "adjusted_mae":
        run_kwargs = {**run_kwargs, "fitness_method": "mae_adjusted"}

    # Template-level wiring is set on the DHPCTIndividual at construction
    # time and baked into the compiled model. It must not flow through to
    # run(); strip it defensively so any caller passing these keys (e.g. an
    # optimizer run_params) doesn't trip ``_run() got an unexpected keyword
    # argument ...``.
    for _template_key in ("top_level_obs_indices", "reference_values"):
        run_kwargs.pop(_template_key, None)

    fitnesses: List[float] = []
    original_seed = self.random_seed
    if evaluation_seed is not None:
        self.evaluation_seed = int(evaluation_seed)
    saved_evaluation_seed = getattr(self, "evaluation_seed", None)
    base_evaluation_seed = (
        int(saved_evaluation_seed) if saved_evaluation_seed is not None else original_seed
    )

    try:
        for i in range(nevals):
            if base_evaluation_seed is not None:
                self.random_seed = int(base_evaluation_seed) + i
            fitnesses.append(float(self.run(**run_kwargs)))
    finally:
        # Initialization metadata belongs to the genome, not the rollout.
        self.random_seed = original_seed

    if aggregate == "mean":
        return float(np.mean(fitnesses))
    if aggregate == "max":
        return float(np.max(fitnesses))
    if aggregate == "min":
        return float(np.min(fitnesses))
    return float(np.median(fitnesses))

DHPCTIndividual.evaluate = _evaluate

